"""Generate the five local SVG editorial illustrations. No hosted assets."""
from pathlib import Path
import shutil, subprocess
root=Path(__file__).resolve().parents[1]/'public/assets/articles'
root.mkdir(parents=True,exist_ok=True)
base='''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 960 600" fill="none"><title>{title}</title><defs><pattern id="grid" width="32" height="32" patternUnits="userSpaceOnUse"><path d="M32 0H0V32" stroke="#62765c" stroke-width=".6" opacity=".18"/></pattern><pattern id="hatch" width="9" height="9" patternUnits="userSpaceOnUse"><path d="M0 9 9 0" stroke="#526c5e" stroke-width="1" opacity=".25"/></pattern></defs><path fill="#eeeee4" d="M0 0H960V600H0Z"/><path fill="url(#grid)" d="M24 24H936V576H24Z"/><g stroke="#526c5e" stroke-width="1"><path d="M24 24H936V576H24ZM24 80H936M24 524H936M690 524V576"/></g><g fill="#526c5e" font-family="monospace" font-size="15" letter-spacing="2"><text x="49" y="59">{heading}</text><text x="49" y="556">FIELD NOTES / ENGINEERING &amp; PEOPLE</text><text x="722" y="556">DWG {number} / NTS</text></g>{drawing}</svg>'''
workflow='''<g stroke="#526c5e" stroke-width="2"><path fill="#526c5e0d" d="M88 134H261V205H88ZM288 134H461V205H288ZM488 134H661V205H488ZM688 134H861V205H688Z"/><path d="M261 170H288M461 170H488M661 170H688"/></g><g fill="#405a49" font-family="monospace" font-size="17"><text x="133" y="177">DESIGN</text><text x="332" y="177">REVIEW</text><text x="545" y="177">TEST</text><text x="736" y="177">RELEASE</text></g><g stroke="#b4bdaa" stroke-width="2">'''+''.join(f'<path d="M90 {260+i*29}H865"/>' for i in range(7))+'''</g><g fill="#526c5e">'''+''.join(f'<path d="M{90+i*26} {252+i*29}h93v15h-93ZM{492+i*26} {252+i*29}h76v15h-76Z"/>' for i in range(7))+'''</g><g fill="#d96747">'''+''.join(f'<path d="M{289+i*34} {252+i*29}h125v15h-125Z"/>' for i in range(7))+'''</g><path d="M292 227H476M292 219v16M476 219v16" stroke="#d96747" stroke-width="2"/><text x="298" y="215" fill="#b65e43" font-family="monospace" font-size="15">THE QUEUE IS WORK TOO</text>'''
measurement='''<g stroke="#526c5e" stroke-width="2"><path fill="url(#hatch)" d="M184 142H776V251H184Z"/><circle cx="222" cy="196" r="17"/><circle cx="738" cy="196" r="17"/><path d="M184 128V100M776 128V100M184 113H776M184 113l15-7m-15 7 15 7M776 113l-15-7m15 7-15 7"/></g><text x="480" y="132" fill="#405a49" font-family="monospace" font-size="19" text-anchor="middle">75.00 ±0.10</text><path fill="#526c5e" opacity=".12" d="M350 287H605V455H350Z"/><path d="M115 455H847M477 287V455" stroke="#526c5e" stroke-width="2" stroke-dasharray="5 6"/><path d="M120 454C260 454 300 454 350 432S412 315 477 315 540 438 605 451 755 454 842 454" stroke="#526c5e" stroke-width="3"/><path d="M120 454C385 454 400 452 456 432S510 315 566 315 628 438 694 451 800 454 842 454" stroke="#d96747" stroke-width="4"/><path d="M477 285H566M477 279V291M566 279V291" stroke="#d96747" stroke-width="2"/><g fill="#526c5e" font-family="monospace" font-size="16"><text x="320" y="486">SPECIFICATION STAYS FIXED</text><text x="578" y="288" fill="#b65e43">BIAS →</text></g>'''
inspection='''<g stroke="#526c5e" stroke-width="2"><path d="M480 126V176M480 176H213V219M480 176V219M480 176H747V219"/><path fill="#526c5e0d" d="M117 219H309V297H117ZM384 219H576V297H384ZM651 219H843V297H651Z"/></g><circle cx="480" cy="127" r="28" fill="url(#hatch)" stroke="#526c5e" stroke-width="2"/><g fill="#405a49" font-family="monospace" font-size="18" text-anchor="middle"><text x="213" y="265">ACCEPT</text><text x="480" y="265">REVIEW</text><text x="747" y="265">REJECT</text></g><path fill="#e7ad62" opacity=".25" d="M421 330H548V461H421Z"/><path d="M421 330V465M548 330V465" stroke="#bd8341" stroke-width="2"/><path d="M100 465H860" stroke="#526c5e" stroke-width="2"/>'''+''.join(f'<circle cx="{130+(i*71)%690}" cy="{350+(i%5)*21}" r="5" fill="{"#d96747" if i%7==0 else "#526c5e"}" opacity=".8"/>' for i in range(70))+'''<g fill="#526c5e" font-family="monospace" font-size="15"><text x="103" y="493">LOW SCORE</text><text x="726" y="493">HIGH SCORE</text></g>'''
ood='<g stroke="#526c5e" stroke-width="2"><ellipse cx="215" cy="220" rx="116" ry="65"/><ellipse cx="215" cy="220" rx="150" ry="88" stroke-dasharray="5 7"/><path d="M382 220H798M760 210l20 10-20 10M100 365H860"/></g><g fill="#526c5e">'+''.join(f'<circle cx="{155+(i*17)%120}" cy="{190+(i*13)%60}" r="4"/>' for i in range(36))+'</g><g fill="#d96747"><circle cx="417" cy="166" r="7"/><circle cx="461" cy="201" r="7"/><circle cx="402" cy="270" r="7"/></g><g fill="#405a49" font-family="monospace" font-size="16"><text x="550" y="174">UNFAMILIAR ≠ WRONG</text><text x="139" y="333">FEATURE REFERENCE</text></g>'+''.join(f'<g><rect x="{100+i*193}" y="385" width="165" height="65" fill="#526c5e0d" stroke="#526c5e"/><text x="{182+i*193}" y="422" text-anchor="middle" fill="#405a49" font-family="monospace" font-size="16">{label}</text></g>' for i,label in enumerate(['MONITOR','LABEL','RETRAIN','EVALUATE']))
chat='<g stroke="#526c5e" stroke-width="2"><rect x="86" y="145" width="270" height="110" rx="8"/><path d="M110 255v24l31-24M116 178h207M116 200h164M116 222h104M380 202H474m-14-8 14 8-14 8"/><rect x="502" y="130" width="366" height="310"/><path d="M502 180H868M502 242H868M502 304H868M502 366H868M710 180V440"/><path d="M680 452v34H218V305m-8 12 8-12 8 12" stroke-dasharray="5 5"/></g><g font-family="monospace" fill="#405a49" font-size="17"><text x="115" y="326">DESCRIBE THE TASK</text><text x="522" y="162">A WORKING COMPARISON</text><text x="524" y="220">ALDER</text><text x="733" y="220">8 DAYS</text><text x="524" y="282">BIRCH</text><text x="733" y="282">12 DAYS</text><text x="524" y="344">CEDAR</text><text x="733" y="344">21 DAYS</text><text x="522" y="410">FILTER / SORT / UNDO</text><text x="253" y="476">REFINE THE SAME WORKSPACE</text></g><circle cx="475" cy="202" r="5" fill="#d96747"/>'
for slug,title,heading,num,drawing in [('where-the-work-waits','Where the work waits','DELIVERY / THE SPACE BETWEEN TASKS','101',workflow),('how-good-is-the-measurement','How good is the measurement?','INSPECTION / CHECK THE REFERENCE','102',measurement),('when-the-model-should-ask-for-help','When the model should ask for help','DECISION / DESIGN THE HANDOFF','103',inspection),('when-the-inputs-change','When the inputs change','OOD / CLOSE THE LEARNING LOOP','104',ood),('the-interface-starts-in-chat','The interface starts in chat','PRODUCT / BUILDING IN CONVERSATION','105',chat)]:
 (root/f'{slug}.svg').write_text(base.format(title=title,heading=heading,number=num,drawing=drawing))
print('Built five local SVG illustrations.')

if shutil.which('rsvg-convert') and shutil.which('magick'):
 for svg in root.glob('*.svg'):
  png=svg.with_suffix('.png')
  subprocess.run(['rsvg-convert','--width','1008','--height','630','--output',str(png),str(svg)],check=True)
  subprocess.run(['magick',str(png),'-background','#eeeee4','-gravity','center','-extent','1200x630',str(png)],check=True)
 print('Built five local PNG images for link previews.')
